package uz.bozor.entity;import jakarta.persistence.*;import lombok.Getter;import lombok.Setter;import java.time.Instant;/** Rasmlar bazada saqlanadi (Render'da disk vaqtinchalik bo'lgani uchun). */@Getter @Setter@Entity @Table(name = "images")public class Image {    @Id    private String id;    @Column(nullable = false)    private String contentType;    @Column(nullable = false, columnDefinition = "bytea")    private byte[] data;    private Instant createdAt;    @PrePersist void onCreate() { createdAt = Instant.now(); }}